use serde_json::json;
use std::path::Path;
use ulw_loop_core::quality_gate::{validate_quality_gate, ValidateQualityGateOptions};
fn gate()->serde_json::Value{json!({"manualQa":{"by":"main-session","status":"passed","evidence":"real evidence","surfaceEvidence":[],"adversarialCases":[],"artifactRefs":[]},"gateReview":{"by":"category:deep","recommendation":"APPROVE","reportPath":"gate-review.md","evidence":"gate evidence","blockers":[]},"iteration":{"fullRerun":true,"status":"passed","rerunCommands":["test"],"evidence":"rerun"},"criteriaCoverage":{"totalCriteria":1,"passCount":1,"originalIntent":"intent","desiredOutcome":"outcome","userOutcomeReview":"review","adversarialClassesCovered":["none"]}})}
#[test]fn reports_multiple_defects(){let mut g=gate();g["gateReview"]["recommendation"]=json!("REJECT");g["manualQa"]["artifactRefs"]=json!([{"id":"a","kind":"invalid-kind","description":"a","path":"missing"}]);let e=validate_quality_gate(&g,None).unwrap_err();let f=e.details.unwrap()["fields"].as_array().unwrap().clone();assert!(f.iter().any(|x|x["field"]=="gateReview.recommendation"));}
#[test]fn reports_empty_artifact_and_defect(){let mut g=gate();g["gateReview"]["recommendation"]=json!("REJECT");g["manualQa"]["artifactRefs"]=json!([{"id":"empty","kind":"cli-transcript","description":"empty","path":"empty.txt"}]);assert!(validate_quality_gate(&g,None).is_err());}
#[test]fn aggregates_independent_defects(){let mut g=gate();g["manualQa"]["evidence"]=json!("placeholder");g["gateReview"]["recommendation"]=json!("REJECT");g["gateReview"]["evidence"]=json!("");assert!(validate_quality_gate(&g,None).unwrap_err().details.unwrap()["fields"].as_array().unwrap().len()>=3);}
#[test]fn reports_missing_required_fields(){let e=validate_quality_gate(&json!({"manualQa":{"evidence":"qa","artifactRefs":[]},"gateReview":{"by":"invalid","recommendation":"REJECT","evidence":"","reportPath":"","blockers":["blocker"]},"iteration":{"fullRerun":false,"status":"failed","rerunCommands":[],"evidence":""},"criteriaCoverage":{"totalCriteria":"bad","passCount":0,"originalIntent":"","desiredOutcome":"","userOutcomeReview":"","adversarialClassesCovered":[]}}),None).unwrap_err();assert!(e.message.contains("gateReview.by"));}
#[test]fn caps_defects_and_flags_truncation(){let mut g=gate();g["manualQa"]["artifactRefs"]=json!((0..30).map(|i|json!({"id":format!("ref-{i}"),"kind":"cli-transcript","description":"artifact","path":format!("missing-{i}")})).collect::<Vec<_>>());let opts=ValidateQualityGateOptions{repo_root:Some(Path::new(".")),fs:None,current_attempt_dir:None,reviewer_surface:None};let e=validate_quality_gate(&g,Some(&opts)).unwrap_err();assert_eq!(e.details.as_ref().unwrap()["fields"].as_array().unwrap().len(),25);assert_eq!(e.details.as_ref().unwrap()["truncated"],true);assert!(e.message.contains("25+"));}
